<script setup lang="ts">import{onMounted,ref}from'vue';import{Building2,MapPin,Package,Plus,Store}from'@lucide/vue';import{api,errorMessage}from'../lib/api';import StatusBadge from'../components/StatusBadge.vue';const listings=ref<any[]>([]),mine=ref<any[]>([]),products=ref<any[]>([]),locations=ref<any[]>([]),mode=ref<'browse'|'manage'>('browse'),selected=ref<any>(),showCreate=ref(false),error=ref(''),success=ref(''),quantity=ref(1),destinationLocationId=ref('');const listing=ref({productId:'',locationId:'',title:'',quantity:1,minimumOrderQuantity:1,unitPrice:1,currency:'EGP'});async function load(){try{const[a,b,c,d]=await Promise.all([api.get('/marketplace/listings'),api.get('/marketplace/my-listings'),api.get('/products',{params:{limit:100}}),api.get('/locations')]);listings.value=a.data.data;mine.value=b.data.data;products.value=c.data.data;locations.value=d.data.data;destinationLocationId.value||=locations.value[0]?.id??'';listing.value.productId||=products.value[0]?.id??'';listing.value.locationId||=locations.value[0]?.id??''}catch(e){error.value=errorMessage(e)}}async function request(){try{await api.post(`/marketplace/listings/${selected.value.id}/requests`,{quantity:quantity.value,destinationLocationId:destinationLocationId.value},{headers:{'Idempotency-Key':crypto.randomUUID()}});success.value='Stock reserved for 15 minutes.';await load()}catch(e){error.value=errorMessage(e)}}async function create(){try{await api.post('/marketplace/listings',listing.value);showCreate.value=false;await load()}catch(e){error.value=errorMessage(e)}}async function setStatus(id:string,status:string){try{await api.patch(`/marketplace/listings/${id}`,{status});await load()}catch(e){error.value=errorMessage(e)}}onMounted(load)</script>
<template><div class="page-heading"><div><p class="eyebrow">B2B NETWORK</p><h1>Marketplace</h1><p>Source stock and publish surplus inventory.</p></div><button class="primary" @click="showCreate=true"><Plus :size="17"/>Create listing</button></div><div class="tabs"><button :class="{active:mode==='browse'}" @click="mode='browse'">Browse network</button><button :class="{active:mode==='manage'}" @click="mode='manage'">My listings</button></div><div v-if="error" class="form-error">{{error}}</div><div v-if="mode==='browse'" class="offer-grid"><article v-for="x in listings" :key="x.id" class="offer-card"><span class="category">{{x.product.category}}</span><h3>{{x.title}}</h3><p class="sku">{{x.sellerSku}}</p><div class="seller"><Building2 :size="17"/><strong>{{x.sellerOrganization.name}}</strong></div><div class="offer-meta"><span><Package :size="16"/>{{x.remainingQuantity}} {{x.product.unit}}</span><span><MapPin :size="16"/>{{x.location.city}}</span></div><div class="price"><strong>{{Number(x.unitPrice).toLocaleString()}} {{x.currency}}</strong><small>Min. {{x.minimumOrderQuantity}}</small></div><button class="primary wide" @click="selected=x;quantity=x.minimumOrderQuantity;success=''">Request stock</button></article></div><article v-else class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Listing</th><th>Location</th><th>Available</th><th>Reserved</th><th>Price</th><th>Status</th><th>Control</th></tr></thead><tbody><tr v-for="x in mine" :key="x.id"><td><strong>{{x.title}}</strong><small>{{x.sellerSku}}</small></td><td>{{x.location.name}}</td><td>{{x.quantityAvailable}}</td><td>{{x.quantityReserved}}</td><td>{{x.unitPrice}} {{x.currency}}</td><td><StatusBadge :status="x.status"/></td><td><button v-if="x.status==='ACTIVE'" class="text-button danger" @click="setStatus(x.id,'PAUSED')">Pause</button><button v-else class="text-button success" @click="setStatus(x.id,'ACTIVE')">Activate</button></td></tr></tbody></table></div></article><div v-if="mode==='browse'&&!listings.length" class="panel empty"><Store/><strong>No active offers</strong></div>
<div v-if="selected" class="modal-backdrop" @click.self="selected=null"><form class="modal" @submit.prevent="request"><h2>{{selected.title}}</h2><label>Destination<select v-model="destinationLocationId"><option v-for="x in locations" :value="x.id">{{x.name}}</option></select></label><label>Quantity<input v-model.number="quantity" type="number" :min="selected.minimumOrderQuantity" :max="selected.remainingQuantity"/></label><div v-if="success" class="success-message">{{success}}</div><div class="modal-actions"><button type="button" class="secondary" @click="selected=null">Close</button><button v-if="!success" class="primary">Reserve</button></div></form></div><div v-if="showCreate" class="modal-backdrop" @click.self="showCreate=false"><form class="modal" @submit.prevent="create"><h2>Create listing</h2><label>Product<select v-model="listing.productId"><option v-for="p in products" :value="p.id">{{p.name}}</option></select></label><label>Location<select v-model="listing.locationId"><option v-for="x in locations" :value="x.id">{{x.name}}</option></select></label><label>Title<input v-model="listing.title" required/></label><div class="form-row"><label>Quantity<input v-model.number="listing.quantity" type="number" min="1"/></label><label>Minimum order<input v-model.number="listing.minimumOrderQuantity" type="number" min="1"/></label></div><label>Unit price<input v-model.number="listing.unitPrice" type="number" min=".01" step=".01"/></label><div class="modal-actions"><button type="button" class="secondary" @click="showCreate=false">Cancel</button><button class="primary">Publish</button></div></form></div></template>
